package main

import "fmt"

func main() {
	var a [3]int // type is [3]int
	var b [4]int // type is [4]int — a different type
	fmt.Printf("%T\n", a)
	fmt.Printf("%T\n", b)
	// a = b // compile error: cannot use b ([4]int) as [3]int
}
// Output:
// [3]int
// [4]int

package main

import "fmt"

func main() {
	a := [3]int{1, 2, 3}
	b := a    // full, independent copy
	b[0] = 9  // mutates only b
	fmt.Println(a)
	fmt.Println(b)
}
// Output:
// [1 2 3]
// [9 2 3]

