package main

import "fmt"

func main() {
	a := [3]int{1, 2, 3}    // explicit length
	b := [...]int{4, 5, 6, 7} // compiler counts -> [4]int
	fmt.Printf("%T %v\n", a, a)
	fmt.Printf("%T %v\n", b, b)
}
// Output:
// [3]int [1 2 3]
// [4]int [4 5 6 7]

