	a := [3]int{1, 2, 3}
	fmt.Println(a[0], a[2]) // valid indices 0..2
	fmt.Println(a == [3]int{1, 2, 3})
	fmt.Println(a == [3]int{1, 2, 4})
	// a[3] would panic: index out of range
}
