package main

import "fmt"

func main() {
	arr := [5]int{10, 20, 30, 40, 50}
	s := arr[1:4] // slice views arr's backing store
	s[0] = 99     // writes through to arr
	fmt.Println(arr)
	fmt.Println(s)
}
// Output:
// [10 99 30 40 50]
// [99 30 40]

