package solution

func Solve(a [5]int) [5]int {
	var out [5]int          // zero-valued result array
	n := len(a)
	for i := 0; i < n; i++ {
		out[(i+1)%n] = a[i] // element i moves to i+1 (mod n)
	}
	return out              // returning an array returns a copy
}

