package solution

import "testing"

func TestSolve(t *testing.T) {
	cases := []struct {
		in, want [5]int
	}{
		{[5]int{1, 2, 3, 4, 5}, [5]int{5, 1, 2, 3, 4}},
		{[5]int{0, 0, 0, 0, 0}, [5]int{0, 0, 0, 0, 0}},
		{[5]int{9, 8, 7, 6, 5}, [5]int{5, 9, 8, 7, 6}},
	}
	for _, c := range cases {
		if got := Solve(c.in); got != c.want { // arrays compare with ==
			t.Errorf("Solve(%v)=%v want %v", c.in, got, c.want)
		}
	}
}

