func scaleAll(a *[3]int) {
	for i := range a {
		a[i] *= 3 // (*a)[i]; modifies the caller's array
	}
}
func main() {
	nums := [3]int{1, 2, 3}
	scaleAll(&nums)   // pass the address
	fmt.Println(nums) // [3 6 9]
}

func Counts(s string) [26]int {
	var freq [26]int            // zero-valued fixed lookup table
	for i := 0; i < len(s); i++ {
		c := s[i]               // c is a byte
		if c >= 'a' && c <= 'z' {
			freq[c-'a']++       // index by offset from 'a'
		}
	}
	return freq                 // returns an independent copy
}

func AreAnagrams(a, b string) bool {
	var fa, fb [26]int // fixed lookup tables, zero-valued
	for i := 0; i < len(a); i++ {
		fa[a[i]-'a']++ // count letters of a
	}
	for i := 0; i < len(b); i++ {
		fb[b[i]-'a']++ // count letters of b
	}
	return fa == fb // arrays of comparable elems compare element-wise
}
